package com.campusiq.common.exception; import com.campusiq.platform.client.PlatformClientException; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.Map; @RestControllerAdvice public class GlobalExceptionHandler { @ExceptionHandler(ApiException.class) ResponseEntity<Map<String,String>> api(ApiException e){return ResponseEntity.status(e.getStatus()).body(Map.of("message",e.getMessage()));} @ExceptionHandler(PlatformClientException.class) ResponseEntity<Map<String,String>> platformUnavailable(PlatformClientException e){return ResponseEntity.status(HttpStatus.BAD_GATEWAY).body(Map.of("message",e.getMessage()));} @ExceptionHandler(org.springframework.web.bind.MethodArgumentNotValidException.class) ResponseEntity<Map<String,String>> validation(){return ResponseEntity.badRequest().body(Map.of("message","Invalid request"));} }
